actions.action:
pc_stav_label: f.pc_stav_label, pc_ziadatel: f.pc_ziadatel,
pc_ziadatel_meno: f.pc_ziadatel_meno, pc_rok: f.pc_rok, pc_mesiac: f.pc_mesiac,
pc_obdobie: f.pc_obdobie, pc_cesty_json: f.pc_cesty_json,
pc_schvalovatel_vyber: f.pc_schvalovatel_vyber, pc_historia: f.pc_historia,
pc_spz: f.pc_spz, pc_palivo: f.pc_palivo, pc_spotreba: f.pc_spotreba,
pc_c_doprava: f.pc_c_doprava, pc_c_miesto_zac: f.pc_c_miesto_zac,
pc_c_cena_phm: f.pc_c_cena_phm;

def ja = loggedUser()
change pc_stav_label value { "rozpisane" }
change pc_ziadatel value { [ja.id] }
change pc_ziadatel_meno value { kto(ja) }
change pc_cesty_json value { "[]" }
change pc_historia value { "" }

// Predvyplneny je MINULY mesiac: vyuctovanie sa pise po tom, co mesiac
// skoncil, nie v jeho priebehu.
def m = java.time.LocalDate.now().minusMonths(1)
change pc_rok value { (m.year as Integer).doubleValue() }
change pc_mesiac value { String.format("%02d", m.monthValue) }
change pc_obdobie value { String.format("%02d/%d", m.monthValue, m.year) }

// Moznosti schvalovatelov sa stavaju TU a nie v `create` casu ako
// `change ... options` - tam sa neuchovaju (B11). Toto je `post` akcia
// udalosti casu, takze uz zapisuje do ulozeneho datasetu.
change pc_schvalovatel_vyber options { schvalovatelia(ja) }

// Podpis je "raz nahrany": skopiruje sa z posledneho vlastneho vyuctovania,
// takze ho clovek prikladá len prvykrat.
prenes_podpis(ja)

// Vozidlo je "raz nastavene": SPZ, palivo a spotreba pridu z profilu
// (`hr/cesty/pc_profil`), ktory si clovek nastavi v menu "Moje vozidlo".
// Ked ho este nema, zalozi sa prazdny - aby ho mal kde vyplnit.
z_profilu(ja, pc_spz, pc_palivo, pc_spotreba, pc_c_doprava, pc_c_miesto_zac, pc_c_cena_phm)

changeCaseProperty("title").about { nazov_casu(pc_obdobie, pc_ziadatel_meno) }
changeCaseProperty("color").about { "grey" }

document.function:
{ def u ->
    // `?.` chrani pred null, nie pred chybajucou property - a na chybajucej
    // vyhodi MissingPropertyException uprostred akcie.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def pc_obdobie, def pc_ziadatel_meno ->
    // BEZ STAVU: `Case.title` je v engine obycajny `String`, takze sa
    // neprekladá. Stav nesie pole `pc_stav_label` a stlpec, nie nazov pripadu.
    def obd = ((pc_obdobie.value ?: "") as String).trim()
    def meno = ((pc_ziadatel_meno.value ?: "") as String).trim()
    return "Travel expenses " + (obd ?: "?") + (meno ? (" - " + meno) : "")
}

{ def pc_rok, def pc_mesiac, def pc_obdobie, def pc_ziadatel_meno ->
    // `pc_obdobie` je to, co ide do tlaciva aj do nazvu pripadu, a drzi sa
    // v samostatnom poli, aby sa dalo hladat a porovnavat (kontrola "jeden
    // clovek, jeden mesiac" stoji prave na nom).
    //
    // Format je "MM/RRRR", nie "Júl 2026": je to hodnota datoveho pola, tie
    // preklad nemaju (CLAUDE.md, Jazyk) - a slovensky nazov mesiaca by
    // v anglickom portali trcal, kym cislo je spravne v oboch.
    int rok = ((pc_rok.value ?: 0) as Number).intValue()
    String mes = ((pc_mesiac.value ?: "") as String)
    change pc_obdobie value { (mes && rok > 0) ? (mes + "/" + rok) : "" }
    changeCaseProperty("title").about { nazov_casu(pc_obdobie, pc_ziadatel_meno) }
}

{ def ja ->
    // Kto smie toto vyuctovanie schvalit. `usersWithRoleAll` je primitivum
    // delegata ("kto vsetko ma rolu X"); `usersWithRole` filtruje ZADANY zoznam,
    // co je ina otazka.
    //
    // ZIADATEL SA ZO ZOZNAMU VYHADZUJE. Styri oci tak nezacinaju odmietnutim,
    // ale tym, ze si clovek sam seba ani nevie vybrat. Guard vo `finish`
    // zostava ako druha linia - pole sa da prepisat cez API.
    def mojeId = (ja?.id ?: "") as String
    def out = [:]
    usersWithRoleAll("veduci", "hr/cesty/pc_vyuctovanie").each { String id ->
        if (id == mojeId) return
        def u = null
        try { u = userService.findById(id, false) } catch (Exception e) { u = null }
        // Kluc moznosti je userId - hex ObjectId, takze v nom nie je `.` ani `$`
        // (Mongo to v nazvoch poli zakazuje, C17).
        out.put(id, u != null ? kto(u) : id)
    }
    return out
}

{ def ja ->
    // Vlastne staršie vyuctovania, od najnovsieho. Dopyt stoji na `author`,
    // nie na `dataSet` - `findCases { it.dataSet... }` nefunguje (gotcha 40),
    // a bez zuzenia na autora by to bol sken vsetkych vyuctovani portalu.
    def mojeId = (ja?.id ?: "") as String
    if (!mojeId) return []
    def vsetky = findCases { qCase ->
        qCase.processIdentifier.eq("hr/cesty/pc_vyuctovanie").and(qCase.author.id.eq(mojeId))
    }
    return (vsetky ?: []).findAll { it.stringId != useCase.stringId }
            .sort { a, b -> (b.creationDate <=> a.creationDate) }
}

{ def ja ->
    // Pripad `hr/cesty/pc_profil` toho cloveka, a ked este nie je, zalozi ho.
    //
    // Lazy zalozenie je zamer: inak by clovek musel vediet, ze si ma najprv
    // niekde nieco nastavit - a to je presne ten krok, ktory nikto neurobi.
    // Takto mu profil vznikne s prvym vyuctovanim a najde ho v menu.
    //
    // `findCases { it.dataSet... }` NEFUNGUJE (petriflow_reference, gotcha 40),
    // takze sa filtruje v Groovy. Pripadov je jeden na cloveka, nie tisice.
    def mojeId = (ja?.id ?: "") as String
    if (!mojeId) return null
    try {
        def vsetky = findCases { it.processIdentifier.eq("hr/cesty/pc_profil") }
        def moj = vsetky?.find { ((it.dataSet?.get("pp_userid")?.value ?: "") as String) == mojeId }
        if (moj != null) return moj
        return createCase("hr/cesty/pc_profil")
    } catch (Exception e) {
        // Chybajuci profil je nepohodlie (vyplni sa rucne), nie chyba -
        // zalozenie vyuctovania na nom padnut nesmie.
        return null
    }
}

{ def ja, def pc_spz, def pc_palivo, def pc_spotreba,
  def pc_c_doprava, def pc_c_miesto_zac, def pc_c_cena_phm ->
    // Predvyplnenie z profilu. Prepisat sa da vsetko - profil je predvolba,
    // nie zamok: kto sel inym autom, cislo zmeni a vyuctovanie je spravne.
    def p = profil(ja)
    if (p == null) return false
    def d = p.dataSet
    def hodnota = { String kluc -> d?.get(kluc)?.value }
    def text = { String kluc -> ((hodnota(kluc) ?: "") as String).trim() }
    def cislo = { String kluc -> ((hodnota(kluc) ?: 0) as Number).doubleValue() }

    if (text("pp_spz")) change pc_spz value { text("pp_spz") }
    if (text("pp_palivo")) change pc_palivo value { text("pp_palivo") }
    if (cislo("pp_spotreba") > 0) change pc_spotreba value { cislo("pp_spotreba") }
    if (text("pp_doprava")) change pc_c_doprava value { text("pp_doprava") }
    if (text("pp_miesto_zac")) change pc_c_miesto_zac value { text("pp_miesto_zac") }
    if (cislo("pp_cena_phm") > 0) change pc_c_cena_phm value { cislo("pp_cena_phm") }
    return true
}

{ def ja ->
    // Podpis sa nahrava RAZ. Kazde dalsie vyuctovanie si ho zoberie
    // z predchadzajuceho - `prenesPrilohu` kopiruje bajty, lebo cesta k prilohe
    // je razena per case a priradenie cudzej cesty by spravilo dva zaznamy nad
    // jednym suborom (zmazanie prveho case-u by vyprazdnilo aj druhy).
    try {
        def predch = moje_predchadzajuce(ja).find { it.dataSet?.get("pc_podpis_zam")?.value != null }
        if (predch == null) return false
        def v = prenesPrilohu(predch.dataSet.get("pc_podpis_zam"), predch.stringId as String, "pc_podpis_zam")
        return (v?.ok ?: false) as boolean
    } catch (Exception e) {
        // Chybajuci podpis je nepohodlie, nie chyba - zalozenie vyuctovania
        // na nom padnut nesmie.
        return false
    }
}

{ ->
    return najnovsiCase("hr/cesty/pc_nastavenia")
}

{ def kluc, def dflt ->
    // Sadzby su v konfiguracii appky, nie v sieti: menia sa zakonom a keby boli
    // v XML, kazda zmena by bola nova verzia siete.
    try {
        def c = nastavenia()
        def v = c?.dataSet?.get(kluc as String)?.value
        return v != null ? (v as Number).doubleValue() : (dflt as Number).doubleValue()
    } catch (Exception e) {
        return (dflt as Number).doubleValue()
    }
}

{ def kluc, def dflt ->
    try {
        def c = nastavenia()
        def v = c?.dataSet?.get(kluc as String)?.value
        def s = v == null ? "" : (v as String)
        return s ? s : (dflt as String)
    } catch (Exception e) {
        return dflt as String
    }
}

{ def od, def doo ->
    // "HH:mm" -> minuty od polnoci. Prichod skorsi nez odchod je cesta cez
    // polnoc, teda +24 h; bez toho by vysla zaporna dlzka a stravne nula.
    def parse = { String s ->
        def m = ((s ?: "") as String).trim() =~ /^(\d{1,2}):(\d{2})$/
        if (!m.matches()) return -1
        int h = m.group(1) as int
        int mi = m.group(2) as int
        if (h > 23 || mi > 59) return -1
        return h * 60 + mi
    }
    int a = parse(od as String)
    int b = parse(doo as String)
    if (a < 0 || b < 0) return -1
    return b >= a ? (b - a) : (b + 1440 - a)
}

{ def min, def strava ->
    // Casove pasma presne ako v tlacive: do 5 h nic, do 12 h prve pasmo,
    // do 18 h druhe, nad 18 h tretie.
    double s1 = sadzba("pcn_strav_5_12", 9.30d)
    double s2 = sadzba("pcn_strav_12_18", 13.80d)
    double s3 = sadzba("pcn_strav_nad_18", 20.60d)
    int m = (min ?: -1) as Integer
    if (m < 0) return 0.0d
    double zaklad = (m <= 300) ? 0.0d : ((m <= 720) ? s1 : ((m <= 1080) ? s2 : s3))
    if (zaklad <= 0.0d) return 0.0d

    // ZRAZKA JE VZDY PERCENTO Z NAJVYSSIEHO PASMA, nie z pasma, do ktoreho
    // cesta spadla. Tak to ma zakon aj tlacivo, a je to to jedine, co sa tu
    // da spravit zle bez toho, aby to bolo vidno.
    double r = sadzba("pcn_zraz_ranajky", 25.0d) / 100.0d * s3
    double o = sadzba("pcn_zraz_obed", 40.0d) / 100.0d * s3
    double v = sadzba("pcn_zraz_vecera", 35.0d) / 100.0d * s3
    def zrazky = ["nie": 0.0d, "ranajky": r, "obed": o, "vecera": v,
                  "ranajky_obed": r + o, "ranajky_vecera": r + v,
                  "obed_vecera": o + v, "ranajky_obed_vecera": r + o + v]
    double zraz = (zrazky.get((strava ?: "nie") as String) ?: 0.0d) as double
    return Math.max(0.0d, zaklad - zraz)
}

{ def km, def doprava ->
    // Zakladna nahrada patri len vlastnemu vozidlu. Firemne auto, vlak
    // a autobus maju v tlacive prazdny stlpec - preplacaju sa inak.
    double k = ((km ?: 0) as Number).doubleValue()
    String d = (doprava ?: "") as String
    if (d == "auto") return k * sadzba("pcn_km_auto", 0.313d)
    if (d == "motocykel") return k * sadzba("pcn_km_motocykel", 0.09d)
    return 0.0d
}

{ def n ->
    // Zaokruhlenie na centy: 0.1 + 0.2 v doublach nie je 0.3 a v sucte
    // tridsiatich ciest to je vidno.
    return Math.round(((n ?: 0) as Number).doubleValue() * 100.0d) / 100.0d
}

{ def pc_cesty_json ->
    def raw = ((pc_cesty_json.value ?: "") as String).trim()
    if (!raw) return []
    try {
        return new groovy.json.JsonSlurper().parseText(raw) as List
    } catch (Exception e) {
        // Rozsypany JSON nesmie zhodit celu akciu - prazdny zoznam je horsi
        // vysledok, ale opravitelny.
        return []
    }
}

{ def c, def spotreba ->
    def s = sumy_cesty(c, spotreba)
    def fmt = { def n -> String.format(java.util.Locale.US, "%.2f", ((n ?: 0) as Number).doubleValue()) }
    double spolu = (s.stravne as double) + (s.zakladna as double) + (s.phm as double) +
            (s.ubytovanie as double) + (s.ine as double)
    int min = s.min as int
    String dlzka = min < 0 ? "?" : (String.format("%d:%02d", (int) (min / 60), min % 60) + " h")
    // Riadok je po ANGLICKY - je to hodnota datoveho pola a tie preklad nemaju
    // (CLAUDE.md, Jazyk).
    return ((c.datum ?: "?") as String) + "  ·  " + ((c.od ?: "?") as String) + "-" +
            ((c.doo ?: "?") as String) + " (" + dlzka + ")  ·  " +
            ((c.rokovanie ?: "-") as String) + "  ·  " + doprava_popis(c.doprava) +
            (((s.km as double) > 0) ? ("  ·  " + fmt(s.km) + " km") : "") +
            "  ·  " + fmt(spolu) + " EUR"
}

{ def kluc ->
    def m = ["auto": "private car", "firemne_auto": "company car",
             "motocykel": "private motorcycle", "firemny_motocykel": "company motorcycle",
             "autobus": "bus", "vlak": "train", "lietadlo": "plane"]
    return (m.get((kluc ?: "") as String) ?: "-") as String
}

{ def kluc ->
    // RETAZCE PRE TLACIVO. Vzorce v hárku porovnavaju stlpec F na presne tieto
    // slova (`IF(F12="Súkromné vozidlo";...)`), takze tu su zamerne po slovensky
    // a s diakritikou - nie je to preklad, je to hodnota, ktoru tlacivo cita.
    // Ked ich uctovna firma prepise, prepise sa aj harok `Zoznamy` a tento zoznam.
    // pflang:off  - CITA TO TLACIVO, NIE CLOVEK
    def m = ["auto": "Súkromné vozidlo", "firemne_auto": "Firemné vozidlo",
             "motocykel": "Súkromný motocykel", "firemny_motocykel": "Firemný motocykel",
             "autobus": "Autobus", "vlak": "Vlak", "lietadlo": "Lietadlo"]
    // pflang:on
    return m.get((kluc ?: "") as String)
}

{ def kluc ->
    // Rovnaky dovod ako pri `doprava_excel`: vzorec pre stravne porovnava
    // stlpec G presne na tieto retazce a odpocitava podla nich zrazku.
    // pflang:off
    def m = ["nie": "Nie", "ranajky": "Áno - raňajky", "obed": "Áno - obed",
             "vecera": "Áno - večera", "ranajky_obed": "Áno - raňajky a obed",
             "ranajky_vecera": "Áno - raňajky a večera",
             "obed_vecera": "Áno - obed a večera",
             "ranajky_obed_vecera": "Áno - raňajky, obed a večera"]
    // pflang:on
    return m.get((kluc ?: "") as String)
}

{ def kluc ->
    // Druh paliva vyberá stlpec v tabulke tyzdennych cien Statistickeho uradu
    // (harok `Priemerné ceny PHM`), takze sa porovnava na presny nazov.
    // pflang:off
    def m = ["benzin_95": "Benzín natural 95", "benzin_98": "Benzín natural 98",
             "benzin_98_100": "Prémiový benzín 98 - 100", "lpg": "LPG",
             "nafta": "Motorová nafta", "nafta_premium": "Prémiová motorová nafta",
             "cng": "CNG", "lng": "LNG", "biolng": "bioLNG", "vodik": "Vodík",
             "el_ac": "El. energia AC nabíjanie", "el_dc": "El. energia DC nabíjanie",
             "el_ultra": "El. energia ultra nabíjanie"]
    // pflang:on
    return m.get((kluc ?: "") as String)
}

{ def pc_cesty_json, def pc_spotreba, def pc_preddavok, def pc_stravne, def pc_zakladna,
  def pc_phm, def pc_ubytovanie, def pc_ine, def pc_spolu, def pc_doplatok, def pc_pocet_ciest ->
    def list = cesty_zo_json(pc_cesty_json)
    double sp = ((pc_spotreba.value ?: 0) as Number).doubleValue()
    double st = 0.0d, za = 0.0d, ph = 0.0d, ub = 0.0d, in_ = 0.0d
    list.each { c ->
        def s = sumy_cesty(c, sp)
        st += (s.stravne as double)
        za += (s.zakladna as double)
        ph += (s.phm as double)
        ub += (s.ubytovanie as double)
        in_ += (s.ine as double)
    }
    // Zakladna nahrada a PHM sa v tlacive scitavaju cez ROUNDUP, ostatne cez
    // SUM. Dodrziavame to, aby sa appka a tlacivo nelisili o cent - a prave
    // o cent by sa to lisilo, keby sa tu zaokruhlovalo matematicky.
    def nahor = { double d -> Math.ceil(d * 100.0d - 1e-9d) / 100.0d }
    double zaR = nahor(za)
    double phR = nahor(ph)
    double spolu = cent(st) + zaR + phR + cent(ub) + cent(in_)

    change pc_stravne value { cent(st) }
    change pc_zakladna value { zaR }
    change pc_phm value { phR }
    change pc_ubytovanie value { cent(ub) }
    change pc_ine value { cent(in_) }
    change pc_spolu value { cent(spolu) }
    change pc_doplatok value { cent(spolu - ((pc_preddavok.value ?: 0) as Number).doubleValue()) }
    change pc_pocet_ciest value { (list.size() as Integer).doubleValue() }
}

{ def pc_cesty_json, def pc_cesty, def pc_cesty_vyber, def pc_spotreba, def pc_preddavok,
  def pc_stravne, def pc_zakladna, def pc_phm, def pc_ubytovanie, def pc_ine,
  def pc_spolu, def pc_doplatok, def pc_pocet_ciest ->
    // Jedno miesto, ktore drzi vykreslenie, moznosti na odobranie a sucty
    // v zhode s JSONom. Kazdy, kto zoznam meni, konci volanim tejto funkcie.
    def list = cesty_zo_json(pc_cesty_json)
    double sp = ((pc_spotreba.value ?: 0) as Number).doubleValue()
    change pc_cesty value {
        list ? list.withIndex(1).collect { c, i -> i + ". " + riadok_cesty(c, sp) }.join("\n") : ""
    }
    // Kluc moznosti nesmie obsahovat `.` ani `$` (C17), preto id typu "c3"
    // a nie datum. Id je POCITADLO ulozene v JSONe, nie index v poli: po
    // odobrani prostrednej cesty by sa indexy posunuli a `multichoice` by
    // odobral inu cestu, nez clovek vybral.
    change pc_cesty_vyber options {
        list.collectEntries { c -> [((c.id ?: "?") as String): riadok_cesty(c, sp)] }
    }
    change pc_cesty_vyber value { [] }
    prepocet(pc_cesty_json, pc_spotreba, pc_preddavok, pc_stravne, pc_zakladna, pc_phm,
             pc_ubytovanie, pc_ine, pc_spolu, pc_doplatok, pc_pocet_ciest)
}

{ def pc_historia, def riadok ->
    def stare = ((pc_historia.value ?: "") as String)
    def novy = java.time.LocalDateTime.now().withNano(0).toString() + "  " + (riadok as String)
    def vsetky = ([novy] + (stare ? stare.split("\n") as List : []))
    // Strop, aby pole nerastlo donekonecna - stare riadky su v audite enginu.
    if (vsetky.size() > 60) vsetky = vsetky[0..59]
    change pc_historia value { vsetky.join("\n") }
}

{ def mapa, def hlavicka, def cesty, def spotreba ->
    // Z mapovania a udajov postavi mapu "bunka -> hodnota". Cele to zije tu,
    // v sieti, aby zmena tlaciva bola zmena konfiguracie a nie kodu.
    def bunky = [:]
    def H = mapa.hlavicka ?: [:]
    def polozka = { def kluc, def hodnota ->
        def ref = H.get(kluc as String)
        if (ref) bunky.put(ref as String, hodnota)
    }
    polozka("spolocnost", hlavicka.spolocnost)
    polozka("sidlo", hlavicka.sidlo)
    polozka("obdobie", hlavicka.obdobie)
    polozka("zamestnanec", hlavicka.zamestnanec)
    polozka("palivo", hlavicka.palivo)
    polozka("spotreba", hlavicka.spotreba)
    polozka("spz", hlavicka.spz)
    polozka("preddavok", hlavicka.preddavok)

    def R = mapa.riadky ?: [:]
    int prvy = ((R.prvy ?: 12) as Number).intValue()
    int krok = Math.max(1, ((R.krok ?: 2) as Number).intValue())
    int max = Math.max(1, ((R.max ?: 31) as Number).intValue())

    // "C" = stlpec C v prvom riadku dvojice, "C+1" = v druhom. Jedna cesta
    // zabera v tlacive dva riadky (Odchod / Príchod).
    def bunka = { def spec, int zaklad ->
        if (!spec) return null
        def casti = (spec as String).split("\\+")
        int off = casti.length > 1 ? (casti[1] as int) : 0
        return casti[0].trim() + (zaklad + off)
    }
    def stlpce = ["datum", "cas_od", "cas_do", "miesto_zac", "miesto_kon", "rokovanie",
                  "doprava", "strava", "km_tam", "km_spat", "ubytovanie", "ine"]

    (0..<max).each { int i ->
        int zaklad = prvy + i * krok
        def c = (i < cesty.size()) ? cesty[i] : null
        if (c == null) {
            // PRAZDNE RIADKY SA CISTIA. Sablona moze byt zosit z minuleho
            // mesiaca (clovek nahra to, co dostal), a bez tohto by v tlacive
            // zostali cudzie cesty pod tymi nasimi. `cena_phm` sa zamerne
            // NEVYPRAZDNUJE - v tom stlpci ma tlacivo vlastny vzorec a na
            // nepouzitom riadku je lepsie nechat ho nedotknuty.
            stlpce.each { String k -> def r = bunka(R.get(k), zaklad); if (r) bunky.put(r, null) }
            return
        }
        def put = { String kluc, def hodnota ->
            def r = bunka(R.get(kluc), zaklad)
            if (r) bunky.put(r, hodnota)
        }
        put("datum", c.datum ? java.time.LocalDate.parse(c.datum as String) : null)
        put("cas_od", c.od ? java.time.LocalTime.parse(dopln_cas(c.od)) : null)
        put("cas_do", c.doo ? java.time.LocalTime.parse(dopln_cas(c.doo)) : null)
        put("miesto_zac", c.miesto_zac)
        put("miesto_kon", c.miesto_kon)
        put("rokovanie", c.rokovanie)
        put("doprava", doprava_excel(c.doprava))
        put("strava", strava_excel(c.strava))
        put("km_tam", ((c.km_tam ?: 0) as Number).doubleValue() ?: null)
        put("km_spat", ((c.km_spat ?: 0) as Number).doubleValue() ?: null)
        put("ubytovanie", ((c.ubytovanie ?: 0) as Number).doubleValue() ?: null)
        put("ine", ((c.ine ?: 0) as Number).doubleValue() ?: null)
        // Cenu PHM tlacivo hlada vo vlastnej tabulke tyzdennych cien
        // Statistickeho uradu. Tu ju zadava ziadatel, takze ten vzorec
        // prepisujeme - je to jediny vzorec, do ktoreho appka siaha.
        put("cena_phm", ((c.cena_phm ?: 0) as Number).doubleValue() ?: null)
    }
    return bunky
}

{ def s ->
    // `LocalTime.parse` chce "HH:mm" s dvojcifernou hodinou; formular pusti "9:30".
    def t = ((s ?: "") as String).trim()
    return (t.length() == 4 && t[1] == ':') ? ("0" + t) : t
}

{ def pc_cesty_json, def pc_spotreba, def pc_obdobie, def pc_ziadatel_meno, def pc_palivo,
  def pc_spz, def pc_preddavok, def pc_podpis_zam, def pc_podpis_schv, def pc_export_sprava ->
    try {
        def cfg = nastavenia()
        if (cfg == null) {
            change pc_export_sprava value { "The application settings case does not exist - no form to fill in." }
            return false
        }
        def raw = ((cfg.dataSet?.get("pcn_mapovanie")?.value ?: "") as String).trim()
        if (!raw) {
            change pc_export_sprava value { "The cell mapping is not set in the application settings." }
            return false
        }
        def mapa = new groovy.json.JsonSlurper().parseText(raw)

        def hlavicka = [
                spolocnost : text_nastavenia("pcn_spolocnost", "Netgrif, s.r.o."),
                sidlo      : text_nastavenia("pcn_sidlo", ""),
                obdobie    : ((pc_obdobie.value ?: "") as String),
                zamestnanec: ((pc_ziadatel_meno.value ?: "") as String),
                palivo     : palivo_excel(pc_palivo.value),
                spotreba   : ((pc_spotreba.value ?: 0) as Number).doubleValue() ?: null,
                spz        : ((pc_spz.value ?: "") as String),
                preddavok  : ((pc_preddavok.value ?: 0) as Number).doubleValue() ?: null]

        def bunky = excel_bunky(mapa, hlavicka, cesty_zo_json(pc_cesty_json),
                                ((pc_spotreba.value ?: 0) as Number).doubleValue())

        // Podpisy. Su to PNG prilohy; ktore su nahrate, tie sa vlozia.
        def P = mapa.podpisy ?: [:]
        def obrazky = []
        def pridaj = { def kluc, def pole ->
            def box = P.get(kluc as String)
            if (box != null && pole?.value != null) {
                obrazky << [subor: pole, bunka: box.bunka, sirka: box.sirka, vyska: box.vyska]
            }
        }
        pridaj("zamestnanec", pc_podpis_zam)
        pridaj("schvalovatel", pc_podpis_schv)

        def nazov = "vyuctovanie-" + ((pc_obdobie.value ?: "") as String).replace("/", "-") + ".xlsx"
        def v = vyplnXlsx([sablona: cfg.dataSet?.get("pcn_sablona"),
                           // pflang:off  - nazov harku v cudzom zosite
                           harok  : text_nastavenia("pcn_harok", "Tuzemská cesta"),
                           // pflang:on
                           bunky  : bunky,
                           obrazky: obrazky,
                           nazov  : nazov,
                           pole   : "pc_vystup",
                           prechod: "t_prehlad"])
        change pc_export_sprava value { (v?.sprava ?: "") as String }
        return (v?.ok ?: false) as boolean
    } catch (Exception e) {
        // Export nesmie zhodit schvalenie. Vyuctovanie je platne aj bez
        // tlaciva; tlacivo sa da vyrobit znova, rozhodnutie nie.
        change pc_export_sprava value { "The form could not be filled in: " + e.message }
        return false
    }
}

actions.action:
pc_c_zaciatok: f.pc_c_zaciatok, pc_c_trvanie: f.pc_c_trvanie,
pc_c_miesto_zac: f.pc_c_miesto_zac, pc_c_miesto_kon: f.pc_c_miesto_kon,
pc_c_rokovanie: f.pc_c_rokovanie, pc_c_doprava: f.pc_c_doprava, pc_c_strava: f.pc_c_strava,
pc_c_km_tam: f.pc_c_km_tam, pc_c_km_spat: f.pc_c_km_spat, pc_c_cena_phm: f.pc_c_cena_phm,
pc_c_ubytovanie: f.pc_c_ubytovanie, pc_c_ine: f.pc_c_ine,
pc_cesty_json: f.pc_cesty_json, pc_cesty: f.pc_cesty, pc_cesty_vyber: f.pc_cesty_vyber,
pc_cesty_sprava: f.pc_cesty_sprava, pc_spotreba: f.pc_spotreba, pc_preddavok: f.pc_preddavok,
pc_stravne: f.pc_stravne, pc_zakladna: f.pc_zakladna, pc_phm: f.pc_phm,
pc_ubytovanie: f.pc_ubytovanie, pc_ine: f.pc_ine, pc_spolu: f.pc_spolu,
pc_doplatok: f.pc_doplatok, pc_pocet_ciest: f.pc_pocet_ciest;

// Button nie je `finish`, takze vynimka by tu nemala komu nic povedat -
// chyba ide do `pc_cesty_sprava` a formular zostane otvoreny.
// Z "kedy to zacalo" a "ako dlho to trvalo" sa dopocita to, co drzi JSON.
def zaciatok = (pc_c_zaciatok.value != null) ? (pc_c_zaciatok.value as java.time.LocalDateTime) : null
double hodin = ((pc_c_trvanie.value ?: 0) as Number).doubleValue()
def koniec = (zaciatok != null && hodin > 0)
        ? zaciatok.plusMinutes(Math.round(hodin * 60d) as long) : null
def datum = (zaciatok != null) ? zaciatok.toLocalDate().toString() : null
def od = (zaciatok != null) ? String.format("%02d:%02d", zaciatok.getHour(), zaciatok.getMinute()) : ""
def doo = (koniec != null) ? String.format("%02d:%02d", koniec.getHour(), koniec.getMinute()) : ""
def doprava = (pc_c_doprava.value ?: "") as String

if (zaciatok == null) {
    change pc_cesty_sprava value { "Fill in when the trip started." }
} else if (hodin <= 0) {
    change pc_cesty_sprava value { "How long did the trip take? Fill in the hours." }
} else if (hodin > 24) {
    // `minuty(od, doo)` pocita cez polnoc, takze nad 24 h by sa dlzka zlomila
    // spat na male cislo a stravne by vyslo nizsie, nez ma byt. Dlhsia cesta
    // sa zapisuje po dnoch - tak to chce aj tlacivo.
    change pc_cesty_sprava value { "A trip longer than 24 hours goes in day by day." }
} else if (!doprava) {
    change pc_cesty_sprava value { "Pick the means of transport." }
} else if ((doprava == "auto" || doprava == "motocykel") &&
           (((pc_c_km_tam.value ?: 0) as Number).doubleValue() +
            ((pc_c_km_spat.value ?: 0) as Number).doubleValue()) <= 0) {
    change pc_cesty_sprava value { "A trip by a private vehicle needs the kilometres driven." }
} else {
    def list = cesty_zo_json(pc_cesty_json)
    // Id je pocitadlo, nie index v poli - po odobrani prostrednej cesty by sa
    // indexy posunuli a zaskrtnutie by ukazovalo na inu cestu.
    def maxId = 0
    list.each { c ->
        def n = ((c.id ?: "c0") as String).replace("c", "")
        if (n.isInteger() && (n as int) > maxId) maxId = n as int
    }
    list << [id        : "c" + (maxId + 1),
             datum     : datum,
             od        : od,
             doo       : doo,
             miesto_zac: ((pc_c_miesto_zac.value ?: "") as String).trim(),
             miesto_kon: ((pc_c_miesto_kon.value ?: "") as String).trim(),
             rokovanie : ((pc_c_rokovanie.value ?: "") as String).trim(),
             doprava   : doprava,
             strava    : ((pc_c_strava.value ?: "nie") as String),
             km_tam    : ((pc_c_km_tam.value ?: 0) as Number).doubleValue(),
             km_spat   : ((pc_c_km_spat.value ?: 0) as Number).doubleValue(),
             cena_phm  : ((pc_c_cena_phm.value ?: 0) as Number).doubleValue(),
             ubytovanie: ((pc_c_ubytovanie.value ?: 0) as Number).doubleValue(),
             ine       : ((pc_c_ine.value ?: 0) as Number).doubleValue()]
    // Poradie v tlacive je chronologicke - tak sa to aj kontroluje.
    list = list.sort { a, b -> ((a.datum ?: "") as String) + ((a.od ?: "") as String) <=>
                               ((b.datum ?: "") as String) + ((b.od ?: "") as String) }
    change pc_cesty_json value { groovy.json.JsonOutput.toJson(list) }
    render_cesty(pc_cesty_json, pc_cesty, pc_cesty_vyber, pc_spotreba, pc_preddavok,
                 pc_stravne, pc_zakladna, pc_phm, pc_ubytovanie, pc_ine,
                 pc_spolu, pc_doplatok, pc_pocet_ciest)
    change pc_cesty_sprava value { "Added: " + datum + " " + od + "-" + doo +
            " (" + list.size() + " on the claim)" }
}

pc_cesty_json: f.pc_cesty_json, pc_cesty: f.pc_cesty, pc_cesty_vyber: f.pc_cesty_vyber,
pc_cesty_sprava: f.pc_cesty_sprava, pc_spotreba: f.pc_spotreba, pc_preddavok: f.pc_preddavok,
pc_stravne: f.pc_stravne, pc_zakladna: f.pc_zakladna, pc_phm: f.pc_phm,
pc_ubytovanie: f.pc_ubytovanie, pc_ine: f.pc_ine, pc_spolu: f.pc_spolu,
pc_doplatok: f.pc_doplatok, pc_pocet_ciest: f.pc_pocet_ciest;

def vybrane = ((pc_cesty_vyber.value ?: []) as List).collect { it as String } as Set
if (!vybrane) {
    change pc_cesty_sprava value { "Nothing is ticked." }
} else {
    def list = cesty_zo_json(pc_cesty_json)
    def zostava = list.findAll { !vybrane.contains((it.id ?: "") as String) }
    change pc_cesty_json value { groovy.json.JsonOutput.toJson(zostava) }
    render_cesty(pc_cesty_json, pc_cesty, pc_cesty_vyber, pc_spotreba, pc_preddavok,
                 pc_stravne, pc_zakladna, pc_phm, pc_ubytovanie, pc_ine,
                 pc_spolu, pc_doplatok, pc_pocet_ciest)
    change pc_cesty_sprava value { "Removed: " + (list.size() - zostava.size()) }
}

pc_rok: f.pc_rok, pc_mesiac: f.pc_mesiac, pc_obdobie: f.pc_obdobie,
pc_ziadatel_meno: f.pc_ziadatel_meno;

obnov_obdobie(pc_rok, pc_mesiac, pc_obdobie, pc_ziadatel_meno)

pc_rok: f.pc_rok, pc_mesiac: f.pc_mesiac, pc_obdobie: f.pc_obdobie,
pc_ziadatel_meno: f.pc_ziadatel_meno;

obnov_obdobie(pc_rok, pc_mesiac, pc_obdobie, pc_ziadatel_meno)

pc_cesty_json: f.pc_cesty_json, pc_cesty: f.pc_cesty, pc_cesty_vyber: f.pc_cesty_vyber,
pc_spotreba: f.pc_spotreba, pc_preddavok: f.pc_preddavok,
pc_stravne: f.pc_stravne, pc_zakladna: f.pc_zakladna, pc_phm: f.pc_phm,
pc_ubytovanie: f.pc_ubytovanie, pc_ine: f.pc_ine, pc_spolu: f.pc_spolu,
pc_doplatok: f.pc_doplatok, pc_pocet_ciest: f.pc_pocet_ciest;

// Spotreba vstupuje do nahrady za PHM na KAZDEJ ceste, takze jej zmena musi
// prepocitat cely zoznam. Bez toho by sucty zostali z predoslej spotreby
// a nic by to nepovedalo.
render_cesty(pc_cesty_json, pc_cesty, pc_cesty_vyber, pc_spotreba, pc_preddavok,
             pc_stravne, pc_zakladna, pc_phm, pc_ubytovanie, pc_ine,
             pc_spolu, pc_doplatok, pc_pocet_ciest)

pc_cesty_json: f.pc_cesty_json, pc_rok: f.pc_rok, pc_mesiac: f.pc_mesiac,
pc_obdobie: f.pc_obdobie, pc_spotreba: f.pc_spotreba, pc_palivo: f.pc_palivo,
pc_schvalovatel_vyber: f.pc_schvalovatel_vyber, pc_ziadatel: f.pc_ziadatel;

// Validacie, ktore `required` neoveri. Odmietnutie vrati HTTP 200 a dovod
// v tele ako `error` - test na stavovy kod taky blok prehliadne.
def list = cesty_zo_json(pc_cesty_json)
if (!list) {
    throw new IllegalStateException("There is no trip on the claim. Add at least one.")
}
def rok = ((pc_rok.value ?: 0) as Number).intValue()
if (rok < 2000 || rok > 2100) {
    throw new IllegalStateException("The year of the claim looks wrong.")
}
if (!((pc_mesiac.value ?: "") as String)) {
    throw new IllegalStateException("Pick the month the claim is for.")
}

// Sukromne vozidlo potrebuje spotrebu, palivo a cenu - bez nich by tlacivo
// vyratalo nahradu za PHM nula a nikto by nepovedal preco.
def sukromne = list.findAll { (it.doprava == "auto" || it.doprava == "motocykel") }
if (sukromne) {
    if (((pc_spotreba.value ?: 0) as Number).doubleValue() <= 0) {
        throw new IllegalStateException(
                "A trip by a private vehicle is on the claim, so the consumption from the registration certificate is needed.")
    }
    if (!((pc_palivo.value ?: "") as String)) {
        throw new IllegalStateException(
                "A trip by a private vehicle is on the claim, so the fuel has to be picked.")
    }
    def bezCeny = sukromne.findAll { ((it.cena_phm ?: 0) as Number).doubleValue() <= 0 }
    if (bezCeny) {
        throw new IllegalStateException(
                "These trips by a private vehicle have no fuel price: " +
                        bezCeny.collect { (it.datum ?: "?") as String }.join(", "))
    }
}

def kto_schvali = ((pc_schvalovatel_vyber.value ?: "") as String)
if (!kto_schvali) {
    throw new IllegalStateException("Pick who is to approve the claim.")
}
// Druha linia styroch oci: zoznam moznosti ziadatela nenesie, ale pole sa da
// prepisat cez API.
def mojeId = (loggedUser().id ?: "") as String
if (kto_schvali == mojeId) {
    throw new IllegalStateException("The claim cannot be approved by the person who submitted it.")
}

// JEDEN CLOVEK, JEDEN MESIAC. Tlacivo je mesacny doklad, takze druhe podane
// vyuctovanie na to iste obdobie je omyl - a bez tejto kontroly by uctaren
// dostala dve a nevedela, ktore plati. Dopyt stoji na `author`, nie na
// `dataSet` (`findCases { it.dataSet... }` nefunguje), takze je zuzeny na
// vlastne pripady tohto cloveka.
def obd = ((pc_obdobie.value ?: "") as String)
def dvojnik = findCases { qCase ->
    qCase.processIdentifier.eq("hr/cesty/pc_vyuctovanie").and(qCase.author.id.eq(mojeId))
}?.find {
    it.stringId != useCase.stringId &&
            ((it.dataSet?.get("pc_obdobie")?.value ?: "") as String) == obd &&
            ((it.dataSet?.get("pc_stav_label")?.value ?: "") as String) != "rozpisane"
}
if (dvojnik != null) {
    throw new IllegalStateException("A claim for " + obd + " has already been submitted.")
}

pc_schvalovatel_vyber: f.pc_schvalovatel_vyber, pc_schvalovatelia: f.pc_schvalovatelia,
pc_schvalovatel_meno: f.pc_schvalovatel_meno, pc_stav_label: f.pc_stav_label,
pc_podane_o: f.pc_podane_o, pc_historia: f.pc_historia, pc_obdobie: f.pc_obdobie,
pc_ziadatel_meno: f.pc_ziadatel_meno, pc_spolu: f.pc_spolu,
pc_cesty_json: f.pc_cesty_json, pc_spotreba: f.pc_spotreba, pc_palivo: f.pc_palivo,
pc_spz: f.pc_spz, pc_preddavok: f.pc_preddavok, pc_podpis_zam: f.pc_podpis_zam,
pc_podpis_schv: f.pc_podpis_schv, pc_export_sprava: f.pc_export_sprava,
pc_komentar: f.pc_komentar;

def id = ((pc_schvalovatel_vyber.value ?: "") as String)
// `userRef` na prechode `t_schvalit` stoji na TOMTO poli. Kym sa nezapise,
// ulohu nema kto prevziat - a nic by to nepovedalo.
change pc_schvalovatelia value { [id] }
def u = null
try { u = userService.findById(id, false) } catch (Exception e) { u = null }
change pc_schvalovatel_meno value { u != null ? kto(u) : id }
change pc_stav_label value { "na_schvalenie" }
change pc_podane_o value { java.time.LocalDateTime.now() }
// Komentar z predchadzajuceho VRATENIA sa tu cisti. Ziadatel ho uz videl
// a v `pc_historia` zostava navzdy; keby zostal v poli, zaznam o dalsom
// rozhodnuti by tvrdil, ze ho schvalovatel napisal znova.
change pc_komentar value { "" }
changeCaseProperty("title").about { nazov_casu(pc_obdobie, pc_ziadatel_meno) }
changeCaseProperty("color").about { "blue" }
do_historie(pc_historia, "submitted by " + ((pc_ziadatel_meno.value ?: "") as String) +
        " (" + String.format(java.util.Locale.US, "%.2f", ((pc_spolu.value ?: 0) as Number).doubleValue()) +
        " EUR) to " + ((pc_schvalovatel_meno.value ?: "") as String))

// Tlacivo sa vyrabia UZ TERAZ, aby schvalovatel videl presne to, co podpisuje,
// a nie len sumu vo formulari.
vyrob_excel(pc_cesty_json, pc_spotreba, pc_obdobie, pc_ziadatel_meno, pc_palivo,
            pc_spz, pc_preddavok, pc_podpis_zam, pc_podpis_schv, pc_export_sprava)

notifikuj(pc_schvalovatelia, "Travel expense claim to approve",
          "A travel expense claim for " + ((pc_obdobie.value ?: "") as String) + " from " +
                  ((pc_ziadatel_meno.value ?: "") as String) + " is waiting for your approval.")

pc_rozhodnutie: f.pc_rozhodnutie, pc_komentar: f.pc_komentar,
go_schvalene: f.go_schvalene, go_vratene: f.go_vratene;

// Routovacie priznaky patria do `phase="pre"`. V `post` sa token pohne
// s nulami a zmizne (reference C4).
def volba = ((pc_rozhodnutie.value ?: "") as String)
if (volba != "schvalit" && volba != "vratit") {
    throw new IllegalStateException("Pick whether the claim is approved or sent back.")
}
if (volba == "vratit" && !((pc_komentar.value ?: "") as String).trim()) {
    throw new IllegalStateException("Sending a claim back needs a comment saying what to correct.")
}
change go_schvalene value { volba == "schvalit" ? 1 : 0 }
change go_vratene value { volba == "vratit" ? 1 : 0 }

go_schvalene: f.go_schvalene, pc_stav_label: f.pc_stav_label,
pc_schvalene_o: f.pc_schvalene_o, pc_historia: f.pc_historia, pc_komentar: f.pc_komentar,
pc_ziadatel: f.pc_ziadatel, pc_obdobie: f.pc_obdobie, pc_ziadatel_meno: f.pc_ziadatel_meno,
pc_cesty_json: f.pc_cesty_json, pc_spotreba: f.pc_spotreba, pc_palivo: f.pc_palivo,
pc_spz: f.pc_spz, pc_preddavok: f.pc_preddavok, pc_podpis_zam: f.pc_podpis_zam,
pc_podpis_schv: f.pc_podpis_schv, pc_export_sprava: f.pc_export_sprava;

boolean schvalene = (((go_schvalene.value ?: 0) as Number).intValue() == 1)
change pc_stav_label value { schvalene ? "na_spracovanie" : "rozpisane" }
changeCaseProperty("color").about { schvalene ? "green" : "orange" }
if (schvalene) {
    change pc_schvalene_o value { java.time.LocalDateTime.now() }
}
do_historie(pc_historia, (schvalene ? "approved" : "sent back") + " by " + kto(loggedUser()) +
        (((pc_komentar.value ?: "") as String).trim() ? (": " + ((pc_komentar.value ?: "") as String).trim()) : ""))

// Tlacivo sa vyraba znova - teraz uz s podpisom schvalovatela.
vyrob_excel(pc_cesty_json, pc_spotreba, pc_obdobie, pc_ziadatel_meno, pc_palivo,
            pc_spz, pc_preddavok, pc_podpis_zam, pc_podpis_schv, pc_export_sprava)

notifikuj(pc_ziadatel,
          schvalene ? "Travel expense claim approved" : "Travel expense claim sent back",
          "Your travel expense claim for " + ((pc_obdobie.value ?: "") as String) +
